import{_ as a,c as e,ag as r,o as d}from"./chunks/framework.BxW8Wou5.js";const p=JSON.parse('{"title":"11、路由","description":"","frontmatter":{},"headers":[],"relativePath":"ruankao/软件设计师/第13章 - 计算机网络/11.路由.md","filePath":"ruankao/软件设计师/第13章 - 计算机网络/11.路由.md","lastUpdated":1762439185000}'),o={name:"ruankao/软件设计师/第13章 - 计算机网络/11.路由.md"};function n(_,t,s,i,l,c){return d(),e("div",null,t[0]||(t[0]=[r('<h1 id="_11、路由" tabindex="-1">11、路由 <a class="header-anchor" href="#_11、路由" aria-label="Permalink to &quot;11、路由&quot;">​</a></h1><p>windows 服务器收到一个 IP 数据包时，先查找主机路由，再查找网络路由（直连和远程），这些路由失败以后再查找默认路由</p><h2 id="类型" tabindex="-1">类型 <a class="header-anchor" href="#类型" aria-label="Permalink to &quot;类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路由类型</th><th>说明</th></tr></thead><tbody><tr><td>直连网络 ID</td><td>用于直接连接的网络，Interface 可以为空</td></tr><tr><td>远程网络 ID</td><td>用于不直接连接的网络，可以通过其他路由器到达这种网络 Interface 字段是本地路由器的 IP 地址</td></tr><tr><td>主机路由</td><td>到达特定主机的路由，子网掩码是 255.255.255.255</td></tr><tr><td>默认路由</td><td>无法找到确定路由时使用的路由，目标网络和网络掩码都是 0.0.0.0</td></tr><tr><td>持久路由</td><td>利用 route add -p 命令添加的表项，每次初始化时，利用这种路由都会加入 Windows 的注册表中，同时加入路由表</td></tr></tbody></table><p><strong>对于某个目标有多条路由，采用距离小的路由来源提供的路由信息</strong></p>',5)]))}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
